/* Toolbox Interactive Academy 2.4.6. Offline, deterministic educational demonstrations. */
(()=>{'use strict';const KEY='toolbox-interactive-246';let done={};try{done=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{};
const courses=[['deck','Deck · COLREGs','Crossing encounter and relative bearing'],['engine','Engine · Pump Circuit','Pump speed and discharge restriction'],['safety','Shared · Fire Safety','Fire triangle and hazard recognition']];
let active='deck',bearing=45,own=12,target=9,speed=70,valve=65,heat=true,fuel=true,oxygen=true;
const css=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const dlg=document.createElement('dialog');dlg.id='ti-dialog';dlg.className='ti-dialog';dlg.innerHTML='<div id="ti-content"></div>';document.body.appendChild(dlg);
function header(title){return `<div class="ti-top"><div><small>TOOLBOX · INTERACTIVE ACADEMY</small><h2>${title}</h2></div><button type="button" class="ti-close" data-ti="close" aria-label="Close">×</button></div><p class="ti-disclaimer">Simplified educational illustration only. Not for navigation, machinery operation, or emergency decision-making. Follow approved procedures and current regulations.</p>`}
function deck(){let type=bearing===0?'Head-on (illustrative)':bearing>0?'Starboard-side crossing (illustrative)':'Port-side crossing (illustrative)';return header('Deck · Encounter Explorer')+`<svg viewBox="0 0 340 210" role="img" aria-label="Top-down two-vessel encounter with adjustable target relative bearing"><rect width="340" height="210" rx="14" fill="#103f3b"/><path d="M0 105H340M170 0V210" stroke="#386d65" stroke-dasharray="5 7"/><g transform="translate(170 150)"><path d="M0 -29 L12 18 L0 12 L-12 18Z" fill="#c3eee1" stroke="white" stroke-width="2"/><text y="40" text-anchor="middle" fill="white" font-size="12">Own ship</text></g><g transform="translate(${170+Math.sin(bearing*Math.PI/180)*95} ${150-Math.cos(bearing*Math.PI/180)*95}) rotate(180)"><path d="M0 -22 L9 14 L0 9 L-9 14Z" fill="#f4c57c" stroke="#ffe3b2" stroke-width="2"/></g><text x="14" y="24" fill="#d7f3eb" font-size="12">Relative bearing ${bearing}°</text><text x="14" y="42" fill="#d7f3eb" font-size="11">Schematic; not to scale</text></svg><label>Target relative bearing <strong>${bearing}°</strong><input data-ti-input="bearing" type="range" min="-90" max="90" step="15" value="${bearing}"></label><div class="ti-result"><strong>${type}</strong><p>${bearing===0?'A nearly reciprocal approach may be a head-on situation. Confirm the actual situation using all available means.':bearing>0?'A target on your starboard side can indicate a crossing situation. If risk of collision exists, the applicable COLREG rules determine obligations.':'A target on your port side can indicate a crossing situation. Do not infer safe passing from relative bearing alone.'}</p><p>Changing one bearing does not establish collision risk. Actual assessment requires relative motion, CPA/TCPA, visibility, and the applicable COLREGs.</p></div><div class="ti-challenge">Challenge: Move the target to starboard, then identify why a single bearing is insufficient to determine collision risk.</div><details class="ti-challenge"><summary>At 10:00 a target bears 082° true at 6 miles. At 10:06 it bears 082° true at 4 miles. What changed?</summary><p>Range closed by 2 miles in six minutes while the compass bearing stayed steady. That trend indicates collision risk. One snapshot on the slider cannot show a trend. See COLREG Rule 7.</p></details><button class="ti-done" data-ti="complete">Mark lesson reviewed</button>`}
function engine(){let index=Math.round(speed*valve/100);return header('Engine · Pump Circuit')+`<svg viewBox="0 0 340 175" role="img" aria-label="Simplified pump and discharge valve diagram"><rect width="340" height="175" rx="14" fill="#103f3b"/><path d="M20 90H120M208 90H320" stroke="#7aa99c" stroke-width="18"/><path d="M20 90H120M208 90H320" stroke="#54d6b0" stroke-width="${Math.max(1,index/10)}" stroke-dasharray="8 6"/><circle cx="165" cy="90" r="43" fill="#237663" stroke="#d2eee2" stroke-width="3"/><path d="M165 64L165 116M139 90H191" stroke="#d2eee2" stroke-width="8"/><path d="M262 90L247 72V108Z M262 90L277 72V108Z" fill="#e7c78d"/><text x="165" y="26" fill="white" text-anchor="middle" font-size="12">Pump</text><text x="262" y="53" fill="white" text-anchor="middle" font-size="12">Valve</text><text x="165" y="157" fill="white" text-anchor="middle" font-size="12">Illustrative flow index: ${index}%</text></svg><label>Pump speed <strong>${speed}%</strong><input data-ti-input="speed" type="range" min="0" max="100" step="5" value="${speed}"></label><label>Discharge valve opening <strong>${valve}%</strong><input data-ti-input="valve" type="range" min="0" max="100" step="5" value="${valve}"></label><div class="ti-result"><strong>${valve<15?'Highly restricted discharge':speed===0?'Pump stopped':'Conceptual flow demonstration'}</strong><p>This flow index is an invented teaching indicator, not an engineering prediction. Actual operating points depend on pump curves, system resistance, suction conditions, and fluid properties.</p></div><div class="ti-challenge">Challenge: Set the flow index between 30% and 40%. ${index>=30&&index<=40?'Challenge achieved.':'Adjust both controls to explore their combined effect.'}</div><details class="ti-challenge"><summary>Set speed to 50% and opening to 80%. Now swap those settings. Can you tell which gives greater actual flow?</summary><p>Both display 40 because this model multiplies the two settings. That equality tells you about the model. To compare actual flow you need measurements or the pump and system curves.</p></details><button class="ti-done" data-ti="complete">Mark lesson reviewed</button>`}
function safety(){let n=[heat,fuel,oxygen].filter(Boolean).length;return header('Shared · Fire Triangle')+`<svg viewBox="0 0 340 180" role="img" aria-label="Fire triangle illustrating heat fuel and oxygen"><rect width="340" height="180" rx="14" fill="#103f3b"/><path d="M170 24L58 151H282Z" fill="none" stroke="${n===3?'#f2bd75':'#82cbbb'}" stroke-width="6"/><text x="170" y="18" text-anchor="middle" fill="white" font-size="14">HEAT</text><text x="44" y="168" fill="white" font-size="14">FUEL</text><text x="238" y="168" fill="white" font-size="14">OXYGEN</text><text x="170" y="108" text-anchor="middle" fill="${n===3?'#ffcc87':'#c1e8dc'}" font-size="19" font-weight="bold">${n===3?'FIRE':'NO FIRE'}</text></svg><div class="ti-checks"><label><input type="checkbox" data-ti-input="heat" ${heat?'checked':''}> Heat present</label><label><input type="checkbox" data-ti-input="fuel" ${fuel?'checked':''}> Fuel present</label><label><input type="checkbox" data-ti-input="oxygen" ${oxygen?'checked':''}> Oxygen present</label></div><div class="ti-result"><strong>${n===3?'All three fire-triangle elements present':'One or more elements removed'}</strong><p>The fire triangle describes basic combustion requirements. Real fire behavior can involve chain reactions, ignition thresholds, ventilation, and complex hazards. Do not use this demonstration to select extinguishing agents or shipboard tactics.</p></div><div class="ti-challenge">Challenge: Remove one element to interrupt the basic fire triangle, then restore all three to compare.</div><details class="ti-challenge"><summary>Switch off heat in the diagram, then restore it. What assumption explains why the flame returns?</summary><p>The diagram assumes fuel and oxygen are still available and that restored heat is sufficient for ignition. It tracks three switches. It cannot tell you the temperature or whether a real space is safe to enter.</p></details><button class="ti-done" data-ti="complete">Mark lesson reviewed</button>`}
function draw(){document.getElementById('ti-content').innerHTML=(active==='deck'?deck():active==='engine'?engine():safety())+`<p class="ti-progress">${done[active]?'Lesson reviewed on this device':'Not yet marked reviewed'} · Works offline after installation</p>`}
function open(id){active=id;draw();if(!dlg.open)dlg.showModal()}
function inject(){const grid=document.querySelector('.tl-root .tl-grid');if(!grid||document.getElementById('ti-launch'))return;const section=document.createElement('section');section.id='ti-launch';section.className='ti-launch';section.innerHTML='<h2>Interactive Systems Academy</h2><p>Explore three offline maritime demonstrations.</p><div class="ti-cards">'+courses.map(([id,t,d])=>`<button type="button" data-ti-open="${id}"><strong>${css(t)}</strong><small>${css(d)}</small><span>${done[id]?'Reviewed · ':''}Explore →</span></button>`).join('')+'</div>';grid.insertAdjacentElement('afterend',section)}
const observer=new MutationObserver(inject);observer.observe(document.getElementById('view'),{childList:true,subtree:false});document.addEventListener('click',e=>{let b=e.target.closest('[data-ti-open],[data-ti]');if(!b)return;if(b.dataset.tiOpen){open(b.dataset.tiOpen);return}if(b.dataset.ti==='close')dlg.close();if(b.dataset.ti==='complete'){done[active]=Date.now();try{localStorage.setItem(KEY,JSON.stringify(done))}catch{}draw()}});dlg.addEventListener('input',e=>{const k=e.target.dataset.tiInput;if(!k)return;let v=e.target.type==='checkbox'?e.target.checked:Number(e.target.value);if(k==='bearing')bearing=v;if(k==='speed')speed=v;if(k==='valve')valve=v;if(k==='heat')heat=v;if(k==='fuel')fuel=v;if(k==='oxygen')oxygen=v;draw()});inject();
})();
